<?php

namespace App\Game;

/**
 * How often a lane strength (BotArranger::strength) beats an opponent's same
 * lane, read from measured percentiles of real bot arrangements
 * (BotStrengthTable, generated by `php artisan pusoy:calibrate-bots`: the bots
 * arrange thousands of random deals against each other and the strengths of
 * every Front, Middle and Back are recorded). An equal strength counts as half
 * a win. Before a table exists a rough category estimate is used.
 */
final class BotStrength
{
    /** @var array<string, list<int>>|null */
    private static ?array $table = null;

    /** @param  'front'|'middle'|'back'  $lane */
    public static function chance(string $lane, int $strength): float
    {
        $sorted = (self::$table ??= self::load())[$lane] ?? [];

        if ($sorted === []) {
            return self::estimate($lane, $strength);
        }

        $below = self::countBelow($sorted, $strength);
        $equalOrBelow = self::countBelow($sorted, $strength + 1);

        return ($below + ($equalOrBelow - $below) / 2) / count($sorted);
    }

    /**
     * Replace the table (calibration) or go back to the shipped one (null).
     *
     * @param  array<string, list<int>>|null  $table
     */
    public static function use(?array $table): void
    {
        self::$table = $table;
    }

    /** @return array<string, list<int>> */
    private static function load(): array
    {
        return class_exists(BotStrengthTable::class) ? BotStrengthTable::LANES : [];
    }

    /** @param  list<int>  $sorted */
    private static function countBelow(array $sorted, int $value): int
    {
        $lo = 0;
        $hi = count($sorted);
        while ($lo < $hi) {
            $mid = intdiv($lo + $hi, 2);
            if ($sorted[$mid] < $value) {
                $lo = $mid + 1;
            } else {
                $hi = $mid;
            }
        }

        return $lo;
    }

    /** Fallback before calibration: category plus top rank on a rough per-lane scale. */
    private static function estimate(string $lane, int $strength): float
    {
        $category = intdiv($strength, 15 ** 5);
        $top = intdiv($strength, 15 ** 4) % 15;
        $scale = [
            'front' => [0.30, 0.75, 0.9, 0.99],
            'middle' => [0.08, 0.35, 0.60, 0.75, 0.84, 0.89, 0.95, 0.99, 1.0, 1.0],
            'back' => [0.02, 0.10, 0.30, 0.50, 0.62, 0.72, 0.85, 0.96, 0.99, 1.0],
        ][$lane];
        $index = $lane === 'front' ? min($category, 3) : $category;
        $base = $scale[$index] ?? 1.0;
        $next = $scale[$index + 1] ?? 1.0;

        return $base + ($next - $base) * max(0, $top - 2) / 12 * 0.8;
    }
}
